let
    подключение = Excel.Workbook(File.Contents(pSource04), null, true),
    сырые_данные = подключение{[Item="Свод",Kind="Sheet"]}[Data],
    поднимаем_заголовки = Table.PromoteHeaders(Table.Skip(сырые_данные, 7), [PromoteAllScalars = true]),
    список_заголовков = List.Select(Table.ColumnNames(поднимаем_заголовки), each Text.Start(_, 6) <> "Column" and _ <> "Холдинг" and Text.Start(_, 2) <> "20"),
    выбираем_столбцы = Table.SelectColumns(поднимаем_заголовки, список_заголовков),
    столбец_фо = Table.AddColumn(выбираем_столбцы, "Федеральный округ", each if Text.AfterDelimiter([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " ") = "федеральный округ" then [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] else null),
    столбец_показатель = Table.AddColumn(столбец_фо, "Показатель", each if List.Contains({"Импорт", "Экспорт", "Запасы на начало месяца", "Производство", "Потребление", "Остатки на конец месяца", "Приток/отток (РФ)"}, [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"]) then [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] else null),
    заполнение_показатель_фо = Table.FillDown(столбец_показатель, {"Федеральный округ", "Показатель"}),
    фильтрация_строк = Table.SelectRows(заполнение_показатель_фо, each ([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> null and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "1" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Дальневосточный федеральный округ" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Запасы на начало месяца" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Импорт" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Остатки на конец месяца" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Потребление" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Приволжский федеральный округ" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Приток/отток (РФ)" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Производство" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Северо-Западный федеральный округ" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Северо-Кавказский федеральный округ" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Сибирский федеральный округ" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Центральный федеральный округ" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Экспорт" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Южный федеральный округ" and [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> "Уральский федеральный округ")),
    столбец_регион = Table.FillDown(Table.AddColumn(фильтрация_строк, "Регион", each if List.Contains({"область", "республика", "автономный", "авт.округ", "край"}, Text.BetweenDelimiters([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " ", " "), Comparer.OrdinalIgnoreCase) and Text.BeforeDelimiter([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " ") <> "Прочие" then [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] else if List.Contains({"область", "республика", "автономный", "авт.округ", "край"}, Text.BeforeDelimiter([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " "), Comparer.OrdinalIgnoreCase) and Text.BeforeDelimiter([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " ") <> "Прочие" then [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] else if List.Contains({"область", "республика", "автономный", "авт.округ", "край"}, Text.AfterDelimiter([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " ", 1), Comparer.OrdinalIgnoreCase) and Text.BeforeDelimiter([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " ") <> "Прочие" then [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] else if List.Contains({"область", "республика", "автономный", "авт.округ", "край"}, Text.BetweenDelimiters([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " ", "-"), Comparer.OrdinalIgnoreCase) and Text.BeforeDelimiter([#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"], " ") <> "Прочие" then [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] else null), {"Регион"}),
    столбец_завод = Table.AddColumn(столбец_регион, "Завод", each if [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] <> [Регион] then [#"Баланс рапсового шрота и рапсового жмыха, тысяч тонн"] else null),
    фильтрация_строк_2 = Table.SelectRows(столбец_завод, each [Показатель] <> "Производство"),
    удаление_вспом_столбцов = Table.SelectColumns(фильтрация_строк_2, List.Select(Table.ColumnNames(фильтрация_строк_2), each Text.Start(_ , 2) <> "Ба" and Text.Start(_ , 2) <> "За")),
    анпивот_таблицы = Table.Unpivot(удаление_вспом_столбцов, List.Select(Table.ColumnNames(удаление_вспом_столбцов), each Text.Start(_, 2) = "01"), "Дата", "Значение"),
    заполняем_пустоты = Table.ReplaceValue(анпивот_таблицы, null, 0, Replacer.ReplaceValue, {"Значение"}),
    меняем_типы = Table.TransformColumnTypes(заполняем_пустоты, {{"Федеральный округ", type text},
                                                                 {"Показатель", type text},
                                                                 {"Регион", type text},
                                                                 {"Дата", type date},
                                                                 {"Значение", type number}}),
    удаляем_дубликаты = Table.Distinct(меняем_типы, {"Показатель", "Регион", "Дата"}),
    финальная_таблица = Table.AddColumn(удаляем_дубликаты, "Код сырья", each "р", type text)
in
    финальная_таблица
